import sys
from typing import List

def p(x: List[int]) -> List[int]:
    y = [0] * (len(x) + 1)
    for i in range(1, len(y)):
        y[i] = y[i-1] + x[i-1]
    return y

def solve(n: int, k: int, a0: List[int]) -> int:
    a = a0[:]
    i = 0
    while True:
        if max(a) >= k:
            return i
        a = [max(0, a[j] - a[j-1]) for j in range(1, len(a))]
        i += 1

def main():
    n, k = map(int, sys.stdin.readline().split())
    a0 = list(map(int, sys.stdin.readline().split()))
    result = solve(n, k, a0)
    print(result)

if __name__ == "__main__":
    main()

def solve():
    n, k = map(int, input().split())
    A = list(map(int, input().split()))

    def p(x):
        m = len(x)
        y = [0] * (m + 1)
        for i in range(1, m + 1):
            y[i] = y[i-1] + x[i-1]
        return y

    i = 0
    while True:
        if any(x >= k for x in A):
